import json

with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

# Let's search for 2003 in the data
def search_2003(obj, context=""):
    found = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if '2003' in str(k) or '2003' in str(v):
                found.append((f"{context}.{k}", v))
            found.extend(search_2003(v, f"{context}.{k}"))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            found.extend(search_2003(item, f"{context}[{i}]"))
    return found

results = search_2003(data)
for path, val in results[:50]:
    print(f"{path}: {val}")
