    data = json.load(f)

# Let's look for the MY-2 table sections in the JSON
def find_my2_tables(obj, path=""):
    if isinstance(obj, dict):
        if 'MY-2' in str(obj.get('title', '')) or 'MY-2' in str(obj.get('name', '')):
            print(f"Found MY-2 at {path}")
            print(json.dumps(obj, indent=2)[:3000])
            print("---")
        for k, v in obj.items():
            find_my2_tables(v, f"{path}.{k}")
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_my2_tables(item, f"{path}[{i}]")

